import sys

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            length = j - i + 1
            freq = {}

            for c in substring:
                freq[c] = freq.get(c, 0) + 1

            max_freq = max(freq.values())

            # Check if substring is diverse
            if max_freq <= length // 2:
                print("YES")
                print(substring)
                return

    print("NO")

if __name__ == "__main__":
    solve()
"}

