def is_valid(root, tree, colors):
    visited = set()
    stack = [(root, -1)]  # (node, parent)

    while stack:
        node, parent = stack.pop()
        if node in visited:
            continue
        visited.add(node)

        # Check if all nodes in subtree rooted at node have the same color
        valid = True
        for neighbor in tree[node]:
            if neighbor == parent:
                continue

            # Check if all nodes in subtree rooted at neighbor have color = colors[neighbor-1]
            for descendant in dfs(neighbor, node, tree, colors):
                if colors[descendant - 1] != colors[neighbor - 1]:
                    valid = False
                    break
            if not valid:
                break

        if not valid:
            return False

    return True

def dfs(start, parent, tree, colors):
    stack = [start]
    visited = set()
    result = []

    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        result.append(node)

        for neighbor in tree[node]:
            if neighbor != parent:
                stack.append(neighbor)

    return result

def solve():
    n = int(input())

    # Build adjacency list
    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        tree[u].append(v)
        tree[v].append(u)

    colors = list(map(int, input().split()))

    # Try each vertex as potential root
    for root in range(1, n + 1):
        if is_valid(root, tree, colors):
            print("YES")
            print(root)
            return

    print("NO")

solve()
