from collections import defaultdict

# Read the bracket string
def solve():
    s = input().strip()
    m = int(input())
    queries = []
    for _ in range(m):
        l, r = map(int, input().split())
        queries.append((l - 1, r - 1))  # 0-indexed

    # For each query, simulate the stack process
    def valid_length(l, r):
        stack = []
        matched = 0
        for i in range(l, r + 1):
            if s[i] == '(':
                stack.append(s[i])
            else:
                if stack:
                    stack.pop()
                    matched += 1
        return 2 * matched

    results = []
    for l, r in queries:
        results.append(str(valid_length(l, r)))

    print('\n'.join(results))

solve()
