n = int(input())
a = list(map(int, input().split()))

# Find all positive numbers
pos = [x for x in a if x > 0]

# Calculate sum of all positive numbers
sum_pos = sum(pos)

# If sum is odd, that's our answer
if sum_pos % 2 == 1:
    print(sum_pos)
else:
    # We need to make it odd
    # Find the smallest positive number
    min_pos = min(pos) if pos else None

    # Find the largest negative number (closest to zero)
    max_neg = max([x for x in a if x < 0]) if any(x < 0 for x in a) else None

    candidates = []
    if min_pos is not None:
        candidates.append(sum_pos - min_pos)
    if max_neg is not None:
        candidates.append(sum_pos + max_neg)

    # Check if we need to remove multiple positives to get odd
    for i in range(2, len(pos) + 1):
        if i % 2 == 0:
            candidates.append(sum_pos - sum(sorted(pos)[:i]))

    # Check if we need to add multiple negatives to get odd
    for i in range(1, len([x for x in a if x < 0]) + 1):
        if i % 2 == 1:
            candidates.append(sum_pos + sum(sorted(a, reverse=True)[:i]))

    # Consider subsets of positives that sum to odd
    for mask in range(1, 1 << len(pos)):
        subset_sum = 0
        for j in range(len(pos)):
            if mask & (1 << j):
                subset_sum += pos[j]
        if subset_sum % 2 == 1:
            candidates.append(subset_sum)

    # Consider subsequences that might not include all positives
    for i in range(1, len(a) + 1):
        for mask in range(1, 1 << len(a)):
            if bin(mask).count('1') == i:
                if sum([a[j] for j in range(len(a)) if mask & (1 << j)]) % 2 == 1:
                    candidates.append(sum([a[j] for j in range(len(a)) if mask & (1 << j)]))

    print(max(candidates))
