import sys

def can_partition_with_sum(ticket: str, n: int, target_sum: int) -> bool:
    current_sum = 0
    segments = 0

    for i in range(n):
        current_sum += int(ticket[i])

        if current_sum == target_sum:
            segments += 1
            current_sum = 0

    return segments >= 2

def is_lucky_ticket(ticket: str, n: int) -> bool:
    total_sum = sum(int(ticket[i]) for i in range(n))

    # Try each possible target sum
    for target in range(1, total_sum + 1):
        print(f"Trying target sum {target}")

        if can_partition_with_sum(ticket, n, target):
            print(f"  Found valid partition for target {target}!")
            return True
    return False

if __name__ == "__main__":
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    ticket = input[1] if len(input) > 1 else ""

    if is_lucky_ticket(ticket, n):
        print("YES")
    else:
        print("NO")
"}

