def compute_parity(perm):
    """Calculate the parity (even/odd) of a permutation."""
    inversions = 0
    n = len(perm)

    for i in range(n):
        for j in range(i + 1, n):
            if perm[i] > perm[j]:
                inversions += 1

    return inversions % 2

def solve():
    n = int(input())
    perm = list(map(int, input().split()))

    parity = compute_parity(perm)

    if n % 2 == 1 and parity == 1:
        print("Petr")
    elif n % 2 == 1 and parity == 0:
        print("Um_nik")
    else:
        print("Petr")

solve()
