def count_bad_numbers(l, r, lcm, min_val):
    count = 0
    for r_val in range(min_val):
        # Count numbers ≡ r_val (mod lcm) in [l, r]
        first = l + (l - r_val - 1) % lcm
        if first < l:
            first += lcm
        last = r - (r - r_val) % lcm
        if last > r:
            last -= lcm
        count += max(0, last - first + 1)
    return count

def solve():
    t = int(input())
    for _ in range(t):
        a, b, q = map(int, input().split())
        lcm = a * b // gcd(a, b)
        min_val = min(a, b)
        results = []
        for _ in range(q):
            l, r = map(int, input().split())
            total = r - l + 1
            bad = count_bad_numbers(l, r, lcm, min_val)
            results.append(str(total - bad))
        print(' '.join(results))

if __name__ == "__main__":
    from math import gcd
    solve()
"}

