for _ in range(t):
    s = sys.stdin.readline().strip()
    countA = s.count('A')
    countB = s.count('B')

    if countB == 0:
        results.append(countA)
    elif countA == 0:
        results.append(0)
    else:
        # Remove one A and one B for each pair
        remove_all_pairs = min(countA, countB)
        remaining_B = countB - remove_all_pairs

        if remaining_B == 0:
            results.append(0)
        elif remaining_B % 2 == 1:
            results.append(1)
        else:
            results.append(0)

