import sys
from collections import deque, defaultdict

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2

    for i in range(n):
        row = []
        for j in range(m):
            row.append(data[idx])
            idx += 1
        grid.append(row)

    # Find all empty cells
    empty_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))

    if not empty_cells:
        # No empty cells, just output the input
        for row in grid:
            sys.stdout.write(''.join(row) + '\n')
        return

    # Check if there's an empty cell with no empty neighbors
    for i, j in empty_cells:
        # Check 4 directions
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m:
                if grid[ni][nj] == '.':
                    break
        else:
            # No empty neighbor
            sys.stdout.write('-1\n')
            return

    # We can always fill if there are no empty cells and we have enough empty cells
    # Since we have at least 2 empty cells and no isolated cells, we can always fill
    # Now let's try to color it

    # We can use BFS to assign alternating colors
    # 0-9 are available, so we need at most 10 colors

    # Create a color matrix
    color = [[-1 for _ in range(m)] for _ in range(n)]

    # BFS queue
    queue = deque()

    # Start from first empty cell
    queue.append(empty_cells[0])
    color[empty_cells[0][0]][empty_cells[0][1]] = 0

    # BFS
    while queue:
        i, j = queue.popleft()

        # Check all 4 directions
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj

            # If the cell is empty and not colored yet
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.' and color[ni][nj] == -1:
                color[ni][nj] = (color[i][j] + 1) % 10
                queue.append((ni, nj))

    # Output the result
    for i in range(n):
        row = []
        for j in range(m):
            if grid[i][j] == '#':
                row.append('#')
            else:
                row.append(str(color[i][j]))
        sys.stdout.write(''.join(row) + '\n')

if __name__ == '__main__':
    solve()
"}

