import sys

def solve():
    n, p = map(int, sys.stdin.readline().split())
    a = []
    b = []
    for _ in range(n):
        ai, bi = map(int, sys.stdin.readline().split())
        a.append(ai)
        b.append(bi)

    # Check if we can run indefinitely
    if sum(a) <= p:
        print(-1)
        return

    # Binary search for maximum time t
    # Upper bound: the time when we charge one device all the time
    max_time = 0
    for i in range(n):
        if a[i] > p:
            max_time = max(max_time, b[i] / (a[i] - p))

    low = 0
    high = max_time * 2  # Add some buffer

    # Binary search
    eps = 1e-8
    for _ in range(100):
        mid = (low + high) / 2
        total = 0
        for i in range(n):
            needed = a[i] * mid - b[i]
            if needed > 0:
                total += needed / p
        if total <= mid + eps:
            low = mid
        else:
            high = mid

    print(f"{low:.10f}")

if __name__ == "__main__":
    solve()
