{"code": "from collections import defaultdict, deque

def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        m = int(data[idx+1])
        a = int(data[idx+2])
        b = int(data[idx+3])
        idx += 4

        graph = defaultdict(list)
        for __ in range(m):
            u = int(data[idx])
            v = int(data[idx+1])
            idx += 2
            graph[u].append(v)
            graph[v].append(u)

        # Find all nodes that are only reachable from a without going through b
        a_visited = {a}
        q = deque([a])
        while q:
            node = q.popleft()
            for neighbor in graph[node]:
                if neighbor not in a_visited and neighbor != b:
                    a_visited.add(neighbor)
                    q.append(neighbor)

        # Find all nodes that are only reachable from b without going through a
        b_visited = {b}
        q = deque([b])
        while q:
            node = q.popleft()
            for neighbor in graph[node]:
                if neighbor not in b_visited and neighbor != a:
                    b_visited.add(neighbor)
                    q.append(neighbor)

        # Valid pairs are between nodes that are only reachable from a and nodes
        # that are only reachable from b (excluding a and b themselves)
        a_only = a_visited - {a, b}
        b_only = b_visited - {a, b}
        results.append(len(a_only) * len(b_only))

    sys.stdout.write("\n".join(map(str, results)))

solve()
