import sys

def can_sort(a, allowed_positions):
    n = len(a)

    # We can sort if for every i, either a[i] == a[i+1],
    # or we can swap at position i, or we can swap at position i+1
    for i in range(n - 1):
        if a[i] > a[i+1]:
            if i not in allowed_positions and i+1 not in allowed_positions:
                return False

    return True

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        m = int(data[idx+1])
        idx += 2

        a = list(map(int, data[idx:idx+n]))
        idx += n

        allowed_positions = set(map(int, data[idx:idx+m]))
        idx += m

        # Check if we can sort the array
        if can_sort(a, allowed_positions):
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

def main():
    solve()

