def parse_artifacts():
    # Read basic artifacts
    basic_artifacts = {}
    for i in range(n):
        name = sys.stdin.readline().strip()
        basic_artifacts[name] = i + 1  # 1-indexed ID

    # Read composite artifacts
    composite_artifacts = []
    for i in range(m):
        line = sys.stdin.readline().strip()
        if not line:
            continue

        # Format: <Art. Name>: <Art. №1> <Art. №1 Number>, ...
        parts = line.split(':')
        art_name = parts[0].strip()
        components = parts[1].strip().split(',')

        comp_dict = {}
        for comp in components:
            # Format: <Art. №X> <Art. №X Number>
            comp_parts = comp.strip().split()
            art_id = int(comp_parts[0])
            count = int(comp_parts[1])
            comp_dict[art_id] = count

        composite_artifacts.append((art_name, comp_dict))

    return basic_artifacts, composite_artifacts

def main():
    # Read first line
    line = sys.stdin.readline()
    while line.strip() == '':
        line = sys.stdin.readline()

    k, n, m, q = map(int, line.strip().split())

    basic_artifacts, composite_artifacts = parse_artifacts()

    # Track artifacts for each ally
    inventory = [{} for _ in range(k)]  # dictionary of artifact counts

    # Process each purchase
    for _ in range(q):
        line = sys.stdin.readline()
        while line.strip() == '':
            line = sys.stdin.readline()

        ally_id, artifact_name = line.strip().split()
        ally_id = int(ally_id) - 1  # 0-indexed

        # Add the basic artifact
        if artifact_name in basic_artifacts:
            art_id = basic_artifacts[artifact_name]
            inventory[ally_id][art_id] = inventory[ally_id].get(art_id, 0) + 1

        # Check if we can craft any composite artifact
        crafted = False

        # Try each composite artifact
        for comp_art_name, comp_requirements in composite_artifacts:
            # Check if all requirements are met
            can_craft = True
            for req_id, req_count in comp_requirements.items():
                if inventory[ally_id].get(req_id, 0) < req_count:
