        # Moves left or down; eventually leaves on the left side
        # At time t, spider is at start_col - t
        max_time = start_col
        for t in range(max_time + 1):
            if start_row - t >= 0:
                spider_at_cell[start_row][start_col][t] += 1
    else:  # 'R' or 'U'
        # Moves right or up; eventually leaves on the right side
        # At time t, spider is at start_col + t
        max_time = (m - 1) - start_col
        for t in range(max_time + 1):
