def solve():
    n = int(input())

    # Dictionary to track count of each value at each time
    from collections import defaultdict

    # maps each value to a dictionary: {time: count}
    value_map = defaultdict(lambda: dict())

    for _ in range(n):
        a, t, x = map(int, input().split())

        # Process the operation
        if a == 1:
            # Add x at time t
            if t in value_map[x]:
                value_map[x][t] += 1
            else:
                value_map[x][t] = 1
        elif a == 2:
            # Remove x at time t
            if t in value_map[x]:
                value_map[x][t] -= 1
                # The problem guarantees this is valid
        elif a == 3:
            # Count x at time t
            count = 0
            if t in value_map[x]:
                count = value_map[x][t]
            # But this is only the count at that exact time
            # We need to consider all times <= t
            for time, cnt in value_map[x].items():
                if time <= t:
                    count += cnt
            print(count)
    return

solve()
