from collections import defaultdict

def solve(n, edges):
    graph = defaultdict(set)
    for a, b in edges:
        graph[a].add(b)
        graph[b].add(a)

    # Each node should have 4 edges
    for node in range(1, n+1):
        if len(graph[node]) != 4:
            return "-1"

    # Try to build the cycle
    cycle = []
    visited = set()

    # Pick any starting node
    start = next(iter(graph))
    visited.add(start)
    cycle.append(start)

    # Build the cycle
    for _ in range(n-1):
        current = cycle[-1]
        neighbors = [x for x in graph[current] if x not in visited]

        # There should be exactly 2 neighbors to choose from (2 immediate neighbors)
        if len(neighbors) != 2:
            return "-1"

        # Choose one (we'll get the other later)
        cycle.append(neighbors[0])
        visited.add(neighbors[0])

    # Verify all edges
    for i in range(n):
        a = cycle[i]
        b = cycle[(i+1)%n]
        # Check immediate neighbors
        if b not in graph[a]:
            return "-1"

        # Check neighbors with common neighbor (distance 2)
        if i > 0:
            if cycle[i-1] not in graph[a]:
                return "-1"
        if i < n-1:
            if cycle[i+1] not in graph[a]:
                return "-1"

    return " ".join(str(x) for x in cycle)

n = int(input())
