import sys

def can_sort_array(a, p):
    n = len(a)

    # Create groups of positions that are connected
    groups = [[] for _ in range(n)]
    visited = [False] * n

    # Connect positions
    for pos in p:
        # If we can swap at position pos, connect pos and pos+1
        if pos + 1 <= n:
            groups[pos].append(pos + 1)
            groups[pos + 1].append(pos)

    # Find connected components using DFS
    for i in range(n):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            group = [i]

            while stack:
                node = stack.pop()
                for neighbor in groups[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        group.append(neighbor)
                        stack.append(neighbor)

    # Get the sorted array
    sorted_a = sorted(a)

    # Check if we can assign values to each position
    for i in range(n):
        # The value at position i in the sorted array must come from the same group
        # Check if we can map a value to this position
        for group in groups:
            # If this group contains position i, check if we can sort it
            if i in group:
                # Extract all values from this group
                group_values = [a[pos] for pos in group]

                # Sort group values
                group_sorted = sorted(group_values)

                # The values at position i in the sorted array must be among these group values
                if sorted_a[i] not in group_sorted:
                    return False

    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
