import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    l = int(data[1])
    k = int(data[2])

    p = [int(data[i])/100.0 for i in range(3, 3+n)]
    a = [int(data[i]) for i in range(3+n, 3+2*n)]

    # DP: dp[i][w][s] = probability after i tours, having won w tours, with s extra space
    # We start with w=0, s=k

    # Initialize DP
    dp = {(0, k): 1.0}

    for i in range(n):
        new_dp = {}

        for state in dp:
            w, s = state
            prob = dp[state]

            # Lose the i-th tour
            if (w, s) not in new_dp:
                new_dp[(w, s)] = 0.0
            new_dp[(w, s)] += prob * (1 - p[i])

            # Win the i-th tour
            ai = a[i]
            if ai == -1:
                # Huge prize, need 1 more space
                if s >= 1:
                    new_w, new_s = w + 1, s - 1
                    if (new_w, new_s) not in new_dp:
                        new_dp[(new_w, new_s)] = 0.0
                    new_dp[(new_w, new_s)] += prob * p[i]
            else:
                # Bag, gain ai space
                new_w, new_s = w + 1, s + ai
                if (new_w, new_s) not in new_dp:
                    new_dp[(new_w, new_s)] = 0.0
                new_dp[(new_w, new_s)] += prob * p[i]

        dp = new_dp

    # Calculate answer: sum of probabilities for all states where w >= l
    answer = 0.0
    for state in dp:
        w, s = state
        if w >= l:
            answer += dp[state]

    print(f"{answer:.12f}")

if __name__ == "__main__":
    solve()
