def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # DP: dp[i] = minimum time to serve people from index i onwards
    dp = [0] * (n + 2)  # dp[n] = 0 (base case)

    # We'll compute dp[i] for i from n-1 down to 0
    for i in range(n-1, -1, -1):
        # We can only choose from the first three available people
        if i + 1 < n:
            time1 = max(a[i], a[i+1]) + dp[i+2]
        else:
            time1 = float('inf')

        if i + 2 < n:
            time2 = max(a[i], a[i+2]) + dp[i+1]
        else:
            time2 = float('inf')

        if i + 2 < n:
            time3 = max(a[i+1], a[i+2]) + dp[i]
        else:
            time3 = float('inf')

        dp[i] = min(time1, time2, time3)

    print(dp[0])

