def solve(n, a):
    """Find the minimum time to serve all customers and output the sequence"""

    # Memoization table for DP
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(i):
        """Return (minimum_time, sequence) for customers from position i onwards"""
        if i >= n:
            return (0, [])

        # Base case: only one customer left
        if i == n - 1:
            return (a[i - 1], [i + 1])  # 1-indexed

        min_time = float('inf')
        best_seq = []

        # Try all three combinations (if possible)
        for i1, i2 in [(i, i+1), (i, i+2), (i+1, i+2)]:
            if i2 >= n:
                continue

            # Get service times
            t1 = a[i1 - 1]
            t2 = a[i2 - 1]

            # Time for this phase
            phase_time = max(t1, t2)

            # Get time and sequence for the rest
            rest_time, rest_seq = dp(i2 + 1)

            # Total time
            total_time = phase_time + rest_time

            # Build sequence
            phase_seq = [(i1 + 1, i2 + 1)]
            if rest_seq:
                phase_seq.extend(rest_seq)

            # Update best
            if total_time < min_time:
                min_time = total_time
                best_seq = phase_seq
            elif total_time == min_time:
                # Tie-breaker: choose lexicographically smaller sequence
                if phase_seq < best_seq:
                    best_seq = phase_seq

        return (min_time, best_seq)

    min_time, seq = dp(1)

    print(min_time)
    for pair in seq:
        if len(pair) == 2:
            print(pair[0], pair[1])
        else:
            print(pair[0])

