def process_segment(segment):
    # Process a single segment between commas
    tokens = []
    i = 0
    while i < len(segment):
        if segment[i] == ' ':
            # This is a space between tokens
            j = i + 1
            while j < len(segment) and segment[j] == '':
                j += 1
            if j < len(segment):
                tokens.append(segment[i:j])
        elif segment[i] == '.':
            if i + 2 < len(segment) and segment[i+1] == '.' and segment[i+2] == '.':
                tokens.append("...")
                i += 3
            else:
                i += 1
        else:  # digit
            j = i + 1
            while j < len(segment) and segment[j].isdigit():
                j += 1
            tokens.append(segment[i:j])
            i = j

    # Join tokens with spaces between numbers and before "..."
    if len(tokens) <= 1:
        return segment

    result = []
    for i, token in enumerate(tokens):
        if token == "...":
            result.append(" ")
        elif i < len(tokens) - 1 and tokens[i+1] != "...":
            result.append(token)
            result.append(" ")
        else:
            result.append(token)

    return ''.join(result)

# Read input
s = input().strip()

# Split by commas
segments = s.split(",")

# Process each segment
processed_segments = []
for segment in segments:
    processed_segment = process_segment(segment)
    processed_segments.append(processed_segment)

# Join segments with ", ", but ensure the last segment doesn't have a trailing space
final_output = ", ".join(processed_segments)

# Print output
print(final_output.strip())
