def shortest_string(s):
    # Count the number of B's
    b_count = s.count("B")

    # Count the number of A's
    a_count = s.count("A")

    # First, remove all "BB" patterns greedily
    while "BB" in s:
        s = s.replace("BB", "", 1)

    # Now look for "AB" patterns in the resulting string
    ab_count = 0
    i = 0
    n = len(s)
    while i < n:
        if s[i] == 'A':
            if i + 1 < n and s[i+1] == 'B':
                ab_count += 1
                i += 2  # skip both characters
            else:
                i += 1
        else:
            i += 1

    remaining_length = len(s) - 2 * ab_count

    return remaining_length

