import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    x = int(data[1])
    y = int(data[2])

    # If the minimum possible sum of numbers (n) exceeds y, impossible
    if n > y:
        print(-1)
        return

    # Start with the maximum spread configuration
    # Largest number: y - n + 1, others: 1
    max_largest = y - n + 1
    result = [max_largest] + [1] * (n - 1)
    sum_squares = max_largest**2 + (n - 1)

    if sum_squares >= x:
        for num in result:
            print(num)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
