import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    results = []

    for _ in range(t):
        n = int(data[idx])
        k = int(data[idx + 1])
        idx += 2

        max_i = 1

        # Find divisors of n
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                # Check divisor i
                if i <= k and i > max_i:
                    max_i = i
                # Check divisor n//i
                if n // i <= k and n // i > max_i:
                    max_i = n // i

        results.append(str(n // max_i))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

