def solve():
    n, m = map(int, input().split())
    segments = set()
    for _ in range(m):
        a, b = map(int, input().split())
        if a > b:
            a, b = b, a
        segments.add((a, b))

    # Check each possible rotation k (1 <= k < n)
    for k in range(1, n):
        new_segments = set()
        for a, b in segments:
            # Rotate both points by k units clockwise
            # In 1-indexed, rotating clockwise by k means adding k
            # If point > n, wrap around by subtracting n
            a_rot = a + k
            if a_rot > n:
                a_rot -= n
            b_rot = b + k
            if b_rot > n:
                b_rot -= n

            # Sort to represent unordered segments
            if a_rot > b_rot:
                a_rot, b_rot = b_rot, a_rot
            new_segments.add((a_rot, b_rot))

        # Check if new_segments matches original segments
        if new_segments == segments:
            print("Yes")
            return

    print("No")

