def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    times = [int(x) for x in data[1:1+n]]

    # DP: dp[i] = min time to serve first i customers
    # dp[i] = min for j in range(max(1, i-2), i) of (dp[j-1] + max(times[j-1], times[i-1]))
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # 0 customers take 0 time

    for i in range(1, n + 1):
        for j in range(max(1, i-2), i):
            dp[i] = min(dp[i], dp[j-1] + max(times[j-1], times[i-1]))

    # Trace back to get the serving order
    result = []
    i = n
    while i > 0:
        for j in range(max(1, i-2), i):
            if dp[i] == dp[j-1] + max(times[j-1], times[i-1]):
                if i - j == 1:
                    # Serve i and j
                    result.append(f"{j} {i}")
                elif j - 1 == 0 and i - j > 1:
                    # Serve j and i
                    result.append(f"{j} {i}")
                elif i - j == 0:
                    # Serve i alone (only when i is odd and j = i-1)
                    result.append(str(j))
                else:
                    # Serve j and i
                    result.append(f"{j} {i}")

                # Move to the previous customers
                i = j - 1
                break

    result.reverse()

    print(dp[n])
    for line in result:
        print(line)

solve()
