from bisect import bisect_right

class FenwickTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (self.size + 1)

    def update(self, idx, delta):
        idx += 1  # 1-indexed
        while idx <= self.size:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        idx += 1  # 1-indexed
        result = 0
        while idx > 0:
            result += self.tree[idx]
            idx -= idx & -idx
        return result

n = int(input())
queries = []

all_moments = set()
for _ in range(n):
    a, t, x = map(int, input().split())
    queries.append((a, t, x))
    all_moments.add(t)

# Coordinate compression
sorted_moments = sorted(all_moments)
moment_to_idx = {t: i for i, t in enumerate(sorted_moments)}

# We'll use Fenwick trees for each integer
# To avoid creating a new Fenwick tree for each integer, we'll use a dictionary
add_tree = {}
remove_tree = {}

for a, t, x in queries:
    if a == 1:
        # Add integer x at moment t
        if x not in add_tree:
            add_tree[x] = FenwickTree(len(sorted_moments))
        add_tree[x].update(moment_to_idx[t], 1)
    elif a == 2:
        # Remove integer x at moment t
        if x not in remove_tree:
            remove_tree[x] = FenwickTree(len(sorted_moments))
        remove_tree[x].update(moment_to_idx[t], 1)
    elif a == 3:
        # Query: count of x at moment t
        idx = moment_to_idx[t]
        count_add = add_tree[x].query(idx) if x in add_tree else 0
        count_remove = remove_tree[x].query(idx) if x in remove_tree else 0
        print(count_add - count_remove)
