    freq[c] = freq.get(c, 0) + 1
    if freq[c] > max_count:
        max_count = freq[c]
        top_char = c

# If the most frequent character appears more than half the length, we need to look for a substring that excludes it
# Otherwise, any substring might be diverse
if max_count > n // 2:
    # Try to find a substring that has at most 2 instances of top_char and the rest are other characters
    found = False
    for i in range(n):
        count = 0
        seen = set()
        for j in range(i, n):
            if s[j] == top_char:
                count += 1
            if count > 2:
                break
            if s[j] not in seen:
                seen.add(s[j])
        # We have a substring from i to j that has at most 2 of top_char and all unique characters
        # But wait, we need to check if the whole substring is diverse
        # Count occurrences in the actual substring
        actual_count = 0
        temp_seen = set()
        for k in range(i, n):
            if s[k] == top_char:
                actual_count += 1
            if s[k] not in temp_seen:
                temp_seen.add(s[k])
            if actual_count > 2:
                break
        # We might have looped through the entire string without finding a substring with at most 2 top_char
        # Let's just keep track of the last valid substring
        if actual_count <= 2:
            found = True
            result = s[i:n]
            break
    if found:
        print("YES")
        print(result)
    else:
        print("NO")
else:
    # We can try to find a substring that has at most half its length as any character
    # Let's try substrings of length at most n
