    n, k = map(int, input().split())

    # Special case for small n
    if n == 1:
        # Only one number, no moves
        print(1)
        return
    elif n == 2:
        # Two numbers, one move
        print(1, k)
        return
    elif n == 3:
        # Three numbers, two moves
        if k == 1:
            print(1, 2, 3)
        else:
            print(-1)
        return
    elif n == 4:
        # Four numbers, three moves
        if k == 1:
            print(1, 2, 3, 4)
        elif k == 2:
            print(2, 4, 3, 1)
        else:
            print(-1)
        return
    elif n == 5:
        # Five numbers, four moves
        if k == 3:
            print(2, 4, 5, 6, 7)
        else:
            print(-1)
        return

    # For larger n, try a general approach
    result = []

    # Use powers of 2 to get high GCDs
    power = 1
    while len(result) < n and power <= 10**9:
        result.append(power)
        power *= 2

    # If we still need more numbers, fill with powers of 2
    # but we need to be careful about distinctness
    if len(result) < n:
