import sys

def is_bad(a, b, x, y):
    """Check if cell (x, y) is bad"""
    return abs(x + y) % (2 * a) == 0 or abs(x - y) % (2 * b) == 0

# Find minimum number of bad cells to visit from (x1, y1) to (x2, y2)
def min_bad_cells(a, b, x1, y1, x2, y2):
    """Try moving in all 4 directions from both start and end to minimize bad cells"
    """""""""""""""""""""""""""""""""""""""""""""""""""""""""""""
    # If we can move directly without any bad cells, return 0
    bad_cells = set()
    if x1 == x2:
        y_coords = range(y1, y2 + 1) if y1 < y2 else range(y1, y2 - 1, -1)
        for y in y_coords:
            if is_bad(a, b, x1, y):
                bad_cells.add((x1, y))
    elif y1 == y2:
        x_coords = range(x1, x2 + 1) if x1 < x2 else range(x1, x2 - 1, -1)
        for x in x_coords:
            if is_bad(a, b, x, y1):
                bad_cells.add((x, y1))
    else:
        # Not aligned, need to think about this
        pass

    if not bad_cells:
        return 0

    # Try moving in all 4 directions from the start
    # For each direction, try to move as far as we can
    directions = [
        (1, 0),  # Right
        (-1, 0), # Left
        (0, 1),  # Down
        (0, -1)  # Up
    ]

    min_bad = float('inf')

    # For each direction from start
    for dx1, dy1 in directions:
        x1_dir, y1_dir = x1 + dx1, y1 + dy1
        # Move as far as we can in this direction without encountering a bad cell
        while True:
            # Check if we're still on the grid
            if not is_bad(a, b, x1_dir, y1_dir):
                # Move another step
                x1_dir += dx1
                y1_dir += dy1
            else:
                break

        # Now we're at a point aligned with the target
        # Try to move from this point to the target
        # For each direction from this point
        for dx2, dy2 in directions:
            x2_dir, y2_dir = x1_dir + dx2, y1_dir + dy2
            # Move as far as we can in this direction without encountering a bad cell
            while True:
                if not is_bad(a, b, x2_dir, y2_dir):
                    x2_dir += dx2
                    y2_dir += dy2
                else:
                    break

            # Now we have a path
            # Count bad cells
            current_x, current_y = x1_dir, y1_dir
            count = 0
            while (current_x, current_y) != (x2_dir, y2_dir):
                if is_bad(a, b, current_x, current_y):
                    count += 1
                current_x += dx2
                current_y += dy2

            min_bad = min(min_bad, count)

    return min_bad

# Read input and solve
if __name__ == "__main__":
    data = list(map(int, sys.stdin.read().split()))
    a, b, x1, y1, x2, y2 = data
    print(min_bad_cells(a, b, x1, y1, x2, y2))
