def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    p = int(data[idx + 1])
    idx += 2

    devices = []
    for _ in range(n):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2
        devices.append((a, b))

    # Binary search on T
    def is_possible(T):
        total_charging_time = 0
        for a, b in devices:
            needed = T * a
            if needed > b:
                total_charging_time += (needed - b) / p
        return total_charging_time <= T

    left = 0.0
    right = 1000000000.0

    for _ in range(100):
        mid = (left + right) / 2
        if is_possible(mid):
            left = mid
        else:
            right = mid

    print(f"{left:.10f}")

if __name__ == "__main__":
    solve()
