def solve():
    n = int(input())
    volumes = []
    for _ in range(n):
        volumes.append(int(input()))

    # Find the initial amount (the most frequent amount)
    from collections import Counter
    count = Counter(volumes)
    initial_amount = volumes[0]  # default to first volume

    # Find the most frequent amount
    for vol in volumes:
        if count[vol] > count[initial_amount]:
            initial_amount = vol

    # Calculate differences from initial amount
    diffs = [v - initial_amount for v in volumes]

    # Count non-zero differences
    nonzero_diffs = [d for d in diffs if d != 0]

    if len(nonzero_diffs) == 0:
        print("Exemplary pages.")
    elif len(nonzero_diffs) == 2:
        # One should be +v, one should be -v
        if abs(nonzero_diffs[0]) == abs(nonzero_diffs[1]) and nonzero_diffs[0] + nonzero_diffs[1] == 0:
            v = abs(nonzero_diffs[0])
            a = diffs.index(-v) + 1  # from cup number
            b = diffs.index(v) + 1  # to cup number
            print(f"{v} ml. from cup #{a} to cup #{b}.")
        else:
            print("Unrecoverable configuration.")
    else:
        print("Unrecoverable configuration.")

solve()
