import sys
from bisect import bisect_right, insort

def solve() -> None:
    n = int(sys.stdin.readline())

    # For each integer, maintain:
    # - list of add times
    # - list of remove times

    integer_map = dict()

    for _ in range(n):
        line = sys.stdin.readline().strip().split()
        a = int(line[0])
        t = int(line[1])
        x = int(line[2])

        if x not in integer_map:
            integer_map[x] = {'add': [], 'remove': []}

        if a == 1:
            integer_map[x]['add'].append(t)
            insort(integer_map[x]['add'], t)
        elif a == 2:
            integer_map[x]['remove'].append(t)
            insort(integer_map[x]['remove'], t)
        elif a == 3:
            add_times = integer_map[x]['add']
            remove_times = integer_map[x]['remove']
            add_count = bisect_right(add_times, t)
            remove_count = bisect_right(remove_times, t)
            print(add_count - remove_count)
        else:
            assert False, "Invalid operation type"

if __name__ == "__main__":
    solve()
