    """Calculate Manhattan distance between two points"""
    return abs(x1 - x2) + abs(y1 - y2)

n, m, x = map(int, input().split())
keyboard = []
for _ in range(n):
    row = input().strip()
    keyboard.append(row)

q = int(input())
text = input().strip()

# Find all lowercase letters and their positions
letters = {}
for i, row in enumerate(keyboard):
    for j, char in enumerate(row):
        if char.islower():
            letters[char] = (i, j)

# Find all Shift keys
shift_keys = []
for i, row in enumerate(keyboard):
    for j, char in enumerate(row):
        if char == 'S':
            shift_keys.append((i, j))

# Process each character in text
other_hand_count = 0

for c in text:
    if c.islower():
        # Regular character
        if c not in letters:
            print(-1)
            exit()
        letter_pos = letters[c]
        # Check if it's at most distance x from any Shift key
        possible = False
        for shift in shift_keys:
            if calculate_distance(letter_pos[0], letter_pos[1], shift[0], shift[1]) <= x:
                possible = True
                break
        if not possible:
            other_hand_count += 1
    else:
        # Uppercase character - needs Shift
        lower = c.lower()
        if lower not in letters:
            print(-1)
            exit()
