def distance(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

n = int(input())
points = [tuple(map(int, input().split())) for _ in range(n)]

# dp[i][j] = maximum perimeter of polygon using points i to j (inclusive)
dp = [[0] * n for _ in range(n)]

# Fill DP table
for i in range(n - 1, -1, -1):
    for j in range(i, n):
        if i == j:
            continue  # only one point, not a polygon
        elif i + 1 == j:
            # Two points: perimeter is 2 * distance between them
            dp[i][j] = 2 * distance(points[i], points[j])
        else:
            # Option 1: use i to j-1 and then add edge from i to j
            option1 = dp[i][j-1] + distance(points[i], points[j])
            # Option 2: use i+1 to j and then add edge from i to i+1
            option2 = dp[i+1][j] + distance(points[i], points[i+1])
            dp[i][j] = max(option1, option2)

# Compute f(3) to f(n)
f = [0] * (n + 1)
for k in range(3, n + 1):
    max_perimeter = 0
    for i in range(n - k + 1):
        j = i + k - 1
        max_perimeter = max(max_perimeter, dp[i][j])
    f[k] = max_perimeter

for k in range(3, n + 1):
    print(f[k], end=' ')
