t = int(input())
for _ in range(t):
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    # Combine and sort: first by b_i ascending (1 then 2), then by a_i descending
    combined = []
    for i in range(n):
        combined.append((b[i], a[i]))
    combined.sort(key=lambda x: (x[0], -x[1]))

    # Use a max-heap for memory and track convenience points
    # And also track which applications were removed

    # For each prefix of the sorted list, consider removing that many applications

    # Try all possible combinations of k1 (b_i=1) and k2 (b_i=2) removed

    # Use prefix sums

    prefix_b1 = [0] * (len(combined) + 1)
    prefix_b2 = [0] * (len(combined) + 1)

    for i in range(len(combined)):
        if combined[i][0] == 1:
            prefix_b1[i+1] = prefix_b1[i] + combined[i][1]
            prefix_b2[i+1] = prefix_b2[i]
        else:
            prefix_b2[i+1] = prefix_b2[i] + combined[i][1]
            prefix_b1[i+1] = prefix_b1[i]

    # Find the minimum convenience points
    min_convenience = float('inf')

    # Try all combinations of k1 and k2 such that k1 + k2 >= 1
    for k1 in range(len(combined) + 1):
        for k2 in range(len(combined) + 1):
            if k1 + k2 == 0:
                continue
            if k1 > len(prefix_b1) or k2 > len(prefix_b2):
                continue
            if prefix_b1[k1] + prefix_b2[k2] >= m:
                min_convenience = min(min_convenience, k1 + 2 * k2)

    if min_convenience == float('inf'):
        print(-1)
    else:
        print(min_convenience)
