import sys

# Parse input
data = sys.stdin.read().strip().split()
if not data:
    exit()

n = int(data[0])
m = int(data[1])
k = int(data[2])

flights = []
index = 3
for _ in range(m):
    di = int(data[index]); fi = int(data[index+1]); ti = int(data[index+2]); ci = int(data[index+3])
    index += 4
    flights.append((di, fi, ti, ci))

# For each city, find the best flight to Metropolis and from Metropolis
# We'll store: (min_day_to_arrive, min_cost_to_arrive, min_day_to_depart, min_cost_to_depart)
# We'll try all possible D values that make sense

# Try to find optimal D
min_cost = float('inf')

# Try D values from 0 to k + n (some upper bound)
# Actually, D can be up to the maximum departure day + n
max_day = 0
for di, fi, ti, ci in flights:
    if ti == 0 and di > max_day:
        max_day = di

# Try D from 0 to max_day + k + 1
for D in range(max_day + k + 1):
    total_cost = 0
    possible = True

    # For each city, check if we can gather them
    for city in range(1, n + 1):
        found_to = False
        found_from = False

        # Check flights from city to Metropolis
        for di, fi, ti, ci in flights:
            if fi == city and ti == 0:
                if di <= D:
                    found_to = True
                    if not found_to or di > min_day_to_arrive[city]:
                        min_day_to_arrive[city] = di
                        min_cost_to_arrive[city] = ci

        if not found_to:
            possible = False
            break

        # Check flights from Metropolis to city
        for di, fi, ti, ci in flights:
            if fi == 0 and ti == city:
                if di >= D + k:
                    found_from = True
                    if not found_from or di < min_day_to_depart[city]:
                        min_day_to_depart[city] = di
                        min_cost_to_depart[city] = ci

        if not found_from:
            possible = False
            break

    if possible:
        total_cost = sum(min_cost_to_arrive[city] + min_cost_to_depart[city] for city in range(1, n + 1))
        if total_cost < min_cost:
            min_cost = total_cost

print(min_cost if min_cost != float('inf') else -1)
