def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input().strip()

        # For each player, determine if they are acting logically
        # For player i:
        # - attacks left (L) -> attacks player i-1
        # - attacks right (R) -> attacks player i+1
        # Player i is attacked by:
        # - player i-1 if player i-1 attacks right (R)
        # - player i+1 if player i+1 attacks left (L)

        # Check who each player is being attacked by
        attacked_by = [[] for _ in range(n)]
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n

            if s[left] == 'R':
                attacked_by[i].append(left)
            if s[right] == 'L':
                attacked_by[i].append(right)

        count = 0
        for i in range(n):
            # If exactly 1 attacker, player should attack that attacker
            if len(attacked_by[i]) == 1:
                attacker = attacked_by[i][0]

                # Check if player attacks the attacker
                if s[i] == 'L':
                    # Should attack left
                    if (i - 1) % n == attacker:
                        continue
                    # Should attack right to match attacker
                    if (i + 1) % n == attacker:
                        count += 1
                else:
                    # Should attack right
                    if (i + 1) % n == attacker:
                        continue
                    # Should attack left to match attacker
                    if (i - 1) % n == attacker:
                        count += 1

        print(count)

solve()

