    for _ in range(2 * n):
        a, b = map(int, input().split())
        graph[a].add(b)
        graph[b].add(a)

    visited = set()

    def dfs(node, path):
        if node in visited:
            return False

        visited.add(node)
        path.append(node)

        # Try each neighbor
        for neighbor in graph[node]:
            # Skip the node we came from (avoid backtracking)
            if len(path) > 1 and path[-2] == neighbor:
                continue

            # Check if we've reached the start node (circular condition)
            if len(path) == n and neighbor == path[0] and path[-1] == path[-2] and len(path) == n:
                return True

            # Check if neighbor has exactly 2 non-visited neighbors
            non_visited_neighbors = [neigh for neigh in graph[neighbor] if neigh not in visited]
            if len(non_visited_neighbors) != 2:
                continue

            if dfs(neighbor, path):
                return True

        path.pop()
        visited.remove(node)
