def solve():
    n = int(input())
    graph = [[] for _ in range(n + 1)]

    for _ in range(2 * n):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)

    # Find a starting node with degree 4
    start = 1
    for i in range(1, n + 1):
        if len(graph[i]) == 4:
            start = i
            break

    order = [start]
    visited = {start}

    # Find immediate neighbors (degree 2) of the start node
    # For a node with degree 4, two of its neighbors will have degree 2 (immediate neighbors)
    neighbor_degrees = {n: len(graph[n]) for n in range(n + 1)}

    # Find immediate neighbors
    for neighbor in graph[start]:
        if neighbor_degrees[neighbor] == 2:
            order.append(neighbor)
            visited.add(neighbor)
            break

    # Now continue building the order
    while len(order) < n:
        current = order[-1]

        # Find the next node
        next_node = None
