def get_square_from_points(p1, p2):
    """Get square with sides parallel to axes from two opposite corners"""
    # p1 = (x1, y1), p2 = (x2, y2)
    x1, y1 = p1
    x2, y2 = p2

    # The square has opposite corners at (x_min, y_min) and (x_max, y_max)
    # So side length a = |x_max - x_min| = |y_max - y_min|
    # We need to find the correct pairing

    # Try all combinations
    if abs(x1 - x2) == abs(y1 - y2):
        # They are opposite corners
        if x1 <= x2 and y1 <= y2:
            return (x1, y1, x2, y2)
        elif x1 >= x2 and y1 >= y2:
            return (x2, y1, x1, y2)
        elif x1 <= x2 and y1 >= y2:
            return (x1, y2, x2, y1)
        else:
            return (x2, y1, x1, y2)
    else:
        # This shouldn't happen per problem statement
        raise ValueError("Points are not opposite corners of a square with sides parallel to axes")


def is_stable_at(brick, com):
    """Check if center of mass com lies within brick's base"""
    x1, y1, x2, y2 = brick
    return (x1 <= com[0] <= x2) and (y1 <= com[1] <= y2)


def compute_center_of_mass(bricks, start_index):
    """Compute center of mass of bricks from start_index to end"""
    total_com = (0.0, 0.0)
    total_weight = 0.0

    for i in range(start_index, len(bricks)):
        brick = bricks[i]
        x1, y1, x2, y2 = brick
        a = abs(x2 - x1)
        weight = a ** 3
        com = ((x1 + x2) / 2, (y1 + y2) / 2)

        total_com = (total_com[0] + weight * com[0], total_com[1] + weight * com[1])
        total_weight += weight

    if total_weight == 0:
        return None

    return (total_com[0] / total_weight, total_com[1] / total_weight)


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    data = list(map(int, data))
    if not data:
        return

    n = data[0]
    bricks = []
    idx = 1

    for i in range(n):
        p1 = (data[idx], data[idx+1])
        p2 = (data[idx+2], data[idx+3])
        idx += 4
        brick = get_square_from_points(p1, p2)
        bricks.append(brick)

    # Try all prefixes
    for k in range(1, n + 1):
        # Check stability for prefix [1..k]
        stable = True

        for i in range(1, k + 1):
            # For brick i, check if COM of bricks i+1..k is in brick i's base
            if i < k:
                com = compute_center_of_mass(bricks, i)
            else:
                com = None

            # If there are no bricks above, stability is trivially true
            if com is None:
                continue

            if not is_stable_at(bricks[i-1], com):
                stable = False
                break

        if not stable:
            print(k - 1)
            return

    print(n)

if __name__ == "__main__":
    import sys
    solve()
