import sys
import math

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    # Parse input
    n = int(data[0])
    m = int(data[1])
    x = int(data[2])

    # Parse keyboard
    board = []
    idx = 3
    for i in range(n):
        row = ""
        for j in range(m):
            row += data[idx]
            idx += 1
        board.append(row)

    # Parse text
    q = int(data[idx])
    text = data[idx + 1]

    # Find positions of letters and Shift keys
    letter_positions = {}
    shift_positions = set()

    for i in range(n):
        for j in range(m):
            char = board[i][j]
            if char == 'S':
                shift_positions.add((i, j))
            else:
                letter_positions[char] = (i, j)

    # Check if character can be typed with one hand
    def can_type_with_one_hand(char):
        if char.isupper():
            # Need a Shift key and the corresponding lowercase letter
            lower_char = char.lower()
            if lower_char not in letter_positions:
                return False  # No such letter on keyboard

            # Try all Shift keys
            for (si, sj) in shift_positions:
                (li, lj) = letter_positions[lower_char]
                if math.sqrt((si - li)**2 + (sj - lj)**2) <= x:
                    return True

            return False  # No Shift key found with appropriate letter nearby
        else:
            # Need the letter itself
            if char in letter_positions:
                return True  # Can type the letter directly

            # Or a Shift key with one hand (press Shift with one hand)
            # Pressing Shift with one hand doesn't need another key
            # So we can type it with one hand if we can press Shift with one hand
            for (si, sj) in shift_positions:
                if math.sqrt((si - 0)**2 + (sj - 0)**2) <= x:
                    return True  # Can press Shift with one hand

            return False  # No letter found and no Shift key nearby

    # Count other hand uses
    other_hand_uses = 0

    for char in text:
        if not can_type_with_one_hand(char):
            other_hand_uses += 1

    print(other_hand_uses)

if __name__ == "__main__":
    main()
