    idx = 3
    for i in range(n):
        row = ""
        for j in range(m):
            row += data[idx]
            idx += 1
        board.append(row)

    # Parse text
    q = int(data[idx])
    text = data[idx + 1]

    # Find positions of letters and Shift keys
    letter_positions = {}
    shift_positions = set()

    for i in range(n):
        for j in range(m):
            char = board[i][j]
            if char == 'S':
                shift_positions.add((i, j))
            else:
                letter_positions[char] = (i, j)

