def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    volumes = [int(data[i + 1]) for i in range(n)]

    # Find the two cups that are different from the rest
    from_cup = None
    to_cup = None

    for i in range(n):
        vol = volumes[i]
        if vol > volumes[0]:
            to_cup = (i + 1, vol)
        elif vol < volumes[0]:
            from_cup = (i + 1, vol)
        # If exactly equal, it's fine

    if from_cup is None and to_cup is None:
        # All equal, no pouring
        print("Exemplary pages.")
    elif from_cup is not None and to_cup is not None:
        # Check if all other cups have the same volume
        base_vol = volumes[0]
        for vol in volumes:
            if vol != base_vol and vol != from_cup[1] and vol != to_cup[1]:
                print("Unrecoverable configuration.")
                return

        # The volume poured is the difference between the two different cups
        volume_poured = abs(from_cup[1] - to_cup[1])
        print(f"{volume_poured} ml. from cup #{from_cup[0]} to cup #{to_cup[0]}.")
    else:
        # More than one pouring or impossible configuration
        print("Unrecoverable configuration.")

if __name__ == "__main__":
    solve()
