def solve():
    start = input().strip()
    end = input().strip()
    k = int(input())

    MOD = 10**9 + 7
    n = len(start)

    # dp[i][j] = number of ways to reach state where word is split at position j after i operations
    dp = [[0] * n for _ in range(k + 1)]

    # Initial state: no operations done, split at every position (but only one word so only split points that give start)
    for j in range(1, n):
        if start[:j] + start[j:] == start:
            dp[0][j] = 1

    for i in range(1, k + 1):
        for j in range(1, n):
            # From state where we split at position j after i-1 operations, we can split at position p (1 <= p <= n-1)
            # This gives us a new state where we split at position (j+p) % n after i operations
            # Actually, after splitting at position p in a word of length n, the new split position is (j+p) % n
            # But we need to be careful: if we split a word that's already been transformed, the indices are different

            # A better approach: dp[i][j] = sum of dp[i-1][prev_j] where prev_j gives j after one split

            # From prev_j, splitting at position p moves the prefix of length p to the end
            # So prev_j + p = j (mod n, since the string wraps around)
            # So prev_j = (j - p) % n

            # But we need to consider all valid p
            for p in range(1, n):
                prev_j = (j - p) % n
                if prev_j > 0 and prev_j < n:
                    dp[i][j] = (dp[i][j] + dp[i-1][prev_j]) % MOD

    # Check if end can be reached from start after k operations by any final split position
    answer = 0
    for j in range(1, n):
        if start[:j] + start[j:] == end:
            answer = (answer + dp[k][j]) % MOD

    print(answer)

solve()
