import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        s = sys.stdin.readline().strip()

        # Use a stack to simulate deletions
        stack = []

        for char in s:
            # Try to delete 'AB'
            if stack and stack[-1] == 'A' and char == 'B':
                stack.pop()  # remove 'A'
                # Don't push 'B' since we deleted
            else:
                stack.append(char)

        # After deleting 'AB', we might have some 'B's left
        # Now delete 'BB' pairs
        i = 0
        n = len(stack)
        while i < n:
            if i + 1 < n and stack[i] == 'B' and stack[i+1] == 'B':
                stack.pop(i)
                stack.pop(i)
                n -= 2
                i = max(0, i - 1)
            else:
                i += 1

        print(len(stack))

if __name__ == "__main__":
    solve()
