    for i in range(1, n + 1):
        # Vertical dominoes from previous column
        if i > 1:
            dp[i] += min(a[i - 2], a[i - 1])  # min of two adjacent columns

        # Horizontal dominoes in this column
        if i == n:
            # Last column can't have horizontal dominoes to the right
            pass
        elif i == 1:
            # First column can't have horizontal dominoes to the left
            pass
        else:
            # Can place horizontal dominoes within column i (using a[i-1] cells)
            dp[i] += min(2, a[i - 1])

    print(dp[n])

