    distinct = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        seen = set()
        cnt = 0
        for j in range(i, n):
            seen.add(a[j])
            cnt += 1
            distinct[i][j] = len(seen)

    # DP: dp[i][j] = maximum total value for first i cakes with j boxes
    dp = [[-1] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for l in range(i):
                if dp[l][j-1] != -1:
                    dp[i][j] = max(dp[i][j], dp[l][j-1] + distinct[l][i-1])

    print(dp[n][k])

solve()
